```python
@gene('s2', 'where to walk: an altar with gems; else cleared groups awaiting capture, else a living camp group, else a free altar', parents=['s2'])
def goals() -> Tiles:
    free_alt = altars() - locked_altars()
    if gems() > 0:
        acc = near(tile(-5, -5), 0)
        for a in free_alt:
            acc = acc | near(a, 1)
        return acc
    acc = near(tile(-5, -5), 0)
    for g in range(num_groups()):
        if group_reward(g):
            acc = acc | group_tiles(g)
    if size(acc) > 0:
        return acc
    for g in range(num_groups()):
        if not group_respawning(g):
            acc = acc | group_tiles(g)
    if size(acc) > 0:
        return acc
    for a in free_alt:
        acc = acc | near(a, 1)
    return acc
```

